#import "SnakeView.h"
#define CELL 16
#define COLS 20
#define ROWS 26
typedef struct { NSInteger x,y; } Point;
@interface SnakeView ()
@property(nonatomic,retain) NSTimer *timer; @property(nonatomic,retain) UIImage *headImage; @property(nonatomic,retain) UIImage *bodyImage; @property(nonatomic,retain) UIImage *foodImage; @property(nonatomic,retain) NSMutableArray *snake; @property(nonatomic,assign) Point dir; @property(nonatomic,assign) Point queued; @property(nonatomic,assign) Point food; @property(nonatomic,assign) NSInteger score; @property(nonatomic,assign) BOOL over;
@end
@implementation SnakeView
- (UIImage *)spriteFromSheet:(UIImage *)sheet x:(CGFloat)x { CGImageRef part=CGImageCreateWithImageInRect(sheet.CGImage,CGRectMake(x,0,64,64)); UIImage *img=[UIImage imageWithCGImage:part scale:sheet.scale orientation:UIImageOrientationUp]; CGImageRelease(part); return img; }
- (id)initWithFrame:(CGRect)f { if((self=[super initWithFrame:f])) { self.backgroundColor=[UIColor colorWithRed:.055 green:.075 blue:.09 alpha:1]; UIImage *sheet=[UIImage imageNamed:@"snake-sprites.png"]; if(sheet){self.headImage=[self spriteFromSheet:sheet x:0];self.bodyImage=[self spriteFromSheet:sheet x:80];self.foodImage=[self spriteFromSheet:sheet x:160];} for(NSNumber *n in @[@(UISwipeGestureRecognizerDirectionUp),@(UISwipeGestureRecognizerDirectionDown),@(UISwipeGestureRecognizerDirectionLeft),@(UISwipeGestureRecognizerDirectionRight)]) { UISwipeGestureRecognizer *g=[[[UISwipeGestureRecognizer alloc] initWithTarget:self action:@selector(swiped:)] autorelease]; g.direction=[n integerValue]; [self addGestureRecognizer:g]; } [self reset]; } return self; }
- (void)dealloc { [self.timer invalidate]; [_timer release]; [_headImage release]; [_bodyImage release]; [_foodImage release]; [_snake release]; [super dealloc]; }
- (Point)point:(NSUInteger)i { Point p; [[self.snake objectAtIndex:i] getValue:&p]; return p; }
- (void)reset { [self.timer invalidate]; self.snake=[NSMutableArray arrayWithObjects:[NSValue valueWithBytes:&(Point){8,13} objCType:@encode(Point)],[NSValue valueWithBytes:&(Point){7,13} objCType:@encode(Point)],[NSValue valueWithBytes:&(Point){6,13} objCType:@encode(Point)],nil]; self.dir=(Point){1,0}; self.queued=self.dir; self.score=0; self.over=NO; [self placeFood]; self.timer=[NSTimer scheduledTimerWithTimeInterval:.16 target:self selector:@selector(step) userInfo:nil repeats:YES]; [self setNeedsDisplay]; }
- (void)placeFood { BOOL ok=NO; while(!ok) { self.food=(Point){arc4random()%COLS,arc4random()%ROWS}; ok=YES; for(NSValue *v in self.snake) { Point p; [v getValue:&p]; if(p.x==self.food.x&&p.y==self.food.y){ok=NO;break;} } } }
- (void)swiped:(UISwipeGestureRecognizer *)g { Point n=self.queued; switch(g.direction){case UISwipeGestureRecognizerDirectionUp:n=(Point){0,-1};break;case UISwipeGestureRecognizerDirectionDown:n=(Point){0,1};break;case UISwipeGestureRecognizerDirectionLeft:n=(Point){-1,0};break;case UISwipeGestureRecognizerDirectionRight:n=(Point){1,0};break;} if(!(n.x==-self.dir.x&&n.y==-self.dir.y)) self.queued=n; if(self.over)[self reset]; }
- (void)step { if(self.over)return; self.dir=self.queued; Point h=[self point:0]; h.x+=self.dir.x; h.y+=self.dir.y; if(h.x<0||h.x>=COLS||h.y<0||h.y>=ROWS){[self end];return;} BOOL eat=h.x==self.food.x&&h.y==self.food.y; NSUInteger count=[self.snake count]-(eat?0:1); for(NSUInteger i=0;i<count;i++){Point p=[self point:i];if(p.x==h.x&&p.y==h.y){[self end];return;}} [self.snake insertObject:[NSValue valueWithBytes:&h objCType:@encode(Point)] atIndex:0]; if(eat){self.score++;[self placeFood];}else [self.snake removeLastObject]; [self setNeedsDisplay]; }
- (void)end { self.over=YES; [self.timer invalidate]; self.timer=nil; [self setNeedsDisplay]; }
- (void)sprite:(UIImage *)img point:(Point)p { if(img)[img drawInRect:CGRectMake(p.x*CELL,52+p.y*CELL,CELL,CELL)]; }
- (void)drawRect:(CGRect)r { CGContextRef c=UIGraphicsGetCurrentContext(); CGContextSetStrokeColorWithColor(c,[[UIColor colorWithWhite:1 alpha:.055] CGColor]); CGContextSetLineWidth(c,.5); for(int x=0;x<=COLS;x++){CGContextMoveToPoint(c,x*CELL,52);CGContextAddLineToPoint(c,x*CELL,52+ROWS*CELL);} for(int y=0;y<=ROWS;y++){CGContextMoveToPoint(c,0,52+y*CELL);CGContextAddLineToPoint(c,COLS*CELL,52+y*CELL);} CGContextStrokePath(c); [[UIColor whiteColor] set]; [@"SNAKE 3GS" drawAtPoint:CGPointMake(12,10) withFont:[UIFont boldSystemFontOfSize:18]]; [[UIColor colorWithWhite:1 alpha:.7] set]; [[NSString stringWithFormat:@"SCORE  %ld",(long)self.score] drawAtPoint:CGPointMake(12,31) withFont:[UIFont systemFontOfSize:12]]; [self sprite:self.foodImage point:self.food]; for(NSUInteger i=0;i<[self.snake count];i++) [self sprite:(i?self.bodyImage:self.headImage) point:[self point:i]]; if(self.over){[[UIColor colorWithWhite:0 alpha:.75] set];UIRectFill(self.bounds);[[UIColor whiteColor] set];[@"GAME OVER" drawAtPoint:CGPointMake(95,230) withFont:[UIFont boldSystemFontOfSize:24]];[@"Swipe or tap to restart" drawAtPoint:CGPointMake(75,263) withFont:[UIFont systemFontOfSize:14]];} }
- (void)touchesEnded:(NSSet *)t withEvent:(UIEvent *)e { if(self.over)[self reset]; }
@end
